package com.hms.website;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.net.IDN; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/website/domains") public class CustomDomainController {private final TenantRepository tenants;private final CustomDomainRepository domains;public CustomDomainController(TenantRepository t,CustomDomainRepository d){tenants=t;domains=d;} @GetMapping public List<CustomDomain> list(@PathVariable String tenantSlug){return domains.findAllByTenantIdOrderByCreatedAtDesc(tenant(tenantSlug));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public CustomDomain add(@PathVariable String tenantSlug,@Valid @RequestBody CustomDomainRequest request){String domain=normalize(request.domain());if(domain.equals("localhost")||domain.startsWith("www."))throw new IllegalArgumentException("Enter the hospital domain without www or localhost");return domains.save(new CustomDomain(tenant(tenantSlug),domain));} @PostMapping("/{domainId}/verify") public CustomDomain verify(@PathVariable String tenantSlug,@PathVariable UUID domainId,@Valid @RequestBody VerifyCustomDomainRequest request){CustomDomain domain=domains.findByIdAndTenantId(domainId,tenant(tenantSlug)).orElseThrow(()->new IllegalArgumentException("Custom domain not found"));domain.verify(request.observedToken());return domains.save(domain);} @DeleteMapping("/{domainId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void disable(@PathVariable String tenantSlug,@PathVariable UUID domainId){CustomDomain domain=domains.findByIdAndTenantId(domainId,tenant(tenantSlug)).orElseThrow(()->new IllegalArgumentException("Custom domain not found"));domain.disable();domains.save(domain);} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));} private String normalize(String raw){String value=raw.trim().toLowerCase();try{String ascii=IDN.toASCII(value);if(ascii.length()>253||!ascii.contains(".")||ascii.contains("/")||ascii.contains(" "))throw new IllegalArgumentException("Invalid custom domain");return ascii;}catch(IllegalArgumentException e){throw new IllegalArgumentException("Invalid custom domain");}}}
